"use client"

import * as React from "react"

import {
  createFileSystemBrowserState,
  createFileSystemPreviewState,
} from "./file-system-browser-state"
import { useFileSystemStateSlices } from "./file-system-controller"
import {
  useFileSystemOpenPreviewController,
  type FileSystemOpenPreviewController,
} from "./file-system-open-preview-state"
import type { FileSystemProps } from "./file-system-types"

export type FileSystemProviderProps = Omit<FileSystemProps, "className"> & {
  children: React.ReactNode
}

export type FileSystemRenderers = {
  renderFileActions?: FileSystemProps["renderFileActions"]
  renderMetadata?: FileSystemProps["renderMetadata"]
}

export type FileSystemCompositionState = {
  openPreview: FileSystemOpenPreviewController
  renderers: FileSystemRenderers
  title: string
}

export type FileSystemContextValue = {
  browser: ReturnType<typeof createFileSystemBrowserState>
  preview: ReturnType<typeof createFileSystemPreviewState>
} & FileSystemCompositionState

const FileSystemContext = React.createContext<FileSystemContextValue | null>(
  null
)

export function useFileSystem() {
  const context = React.useContext(FileSystemContext)
  if (!context) {
    throw new Error("useFileSystem must be used within FileSystemProvider.")
  }
  return context
}

export function FileSystemProvider({
  items,
  children,
  defaultPath,
  defaultQuery,
  defaultSelectedPath,
  defaultView = "list",
  loadChildren,
  onPathChange,
  onQueryChange,
  onFileOpen,
  onSelectionChange,
  onViewChange,
  path,
  query,
  renderFileActions,
  renderMetadata,
  resolveSource,
  selectedPath,
  title = "Files",
  view,
}: FileSystemProviderProps) {
  const state = useFileSystemStateSlices({
    defaultPath,
    defaultQuery,
    defaultSelectedPath,
    defaultView,
    items,
    loadChildren,
    onPathChange,
    onQueryChange,
    onSelectionChange,
    onViewChange,
    path,
    query,
    resolveSource,
    selectedPath,
    view,
  })
  const browser = React.useMemo(
    () => createFileSystemBrowserState(state),
    [
      state.index,
      state.loading,
      state.navigation,
      state.query,
      state.selection,
      state.view,
    ]
  )
  const preview = React.useMemo(
    () => createFileSystemPreviewState(state),
    [state.selection, state.source]
  )
  const openPreview = useFileSystemOpenPreviewController({
    onFileOpen,
    resolveFileSource: state.source.resolveFileSource,
  })
  const renderers = React.useMemo<FileSystemRenderers>(
    () => ({ renderFileActions, renderMetadata }),
    [renderFileActions, renderMetadata]
  )
  const value = React.useMemo<FileSystemContextValue>(
    () => ({
      browser,
      preview,
      openPreview,
      renderers,
      title,
    }),
    [browser, openPreview, preview, renderers, title]
  )

  return (
    <FileSystemContext.Provider value={value}>
      {children}
    </FileSystemContext.Provider>
  )
}

"use client"

import * as React from "react"

import type {
  FileSystemHeaderState,
  FileSystemPreviewState as FileSystemPreviewDomainState,
} from "./file-system-browser-state"
import { createFileSystemHeaderState } from "./file-system-browser-state"
import {
  createFileSystemBrowserController,
  type FileSystemBrowserController,
} from "./file-system-browser-controller"
import { FileSystemColumnsView } from "./file-system-columns-view"
import {
  FileSystemCommandBar,
  FileSystemStatusBar,
  FileSystemToolbar,
} from "./file-system-controls"
import { FileSystemGridView } from "./file-system-grid-view"
import { FileSystemListView } from "./file-system-list-view"
import { FileSystemPreviewPanel } from "./file-system-preview"
import { useFileSystem } from "./file-system-provider"
import type { FileSystemProps } from "./file-system-types"

export type FileSystemBrowserPartState = FileSystemBrowserController

export type { FileSystemHeaderState } from "./file-system-browser-state"

export type FileSystemPreviewState = FileSystemPreviewDomainState & {
  renderFileActions?: FileSystemProps["renderFileActions"]
  renderMetadata?: FileSystemProps["renderMetadata"]
}

export function useFileSystemHeader(): FileSystemHeaderState {
  const state = useFileSystem()

  return createFileSystemHeaderState({
    browser: state.browser,
    title: state.title,
  })
}

export function useFileSystemBrowser(): FileSystemBrowserPartState {
  const state = useFileSystem()

  return createFileSystemBrowserController({
    browser: state.browser,
    openPreview: state.openPreview.open,
    resolveFileSource: state.preview.resolveSource,
  })
}

export function useFileSystemPreview(): FileSystemPreviewState {
  const state = useFileSystem()

  return {
    ...state.preview,
    renderFileActions: state.renderers.renderFileActions,
    renderMetadata: state.renderers.renderMetadata,
  }
}

export function FileSystemHeader() {
  const header = useFileSystemHeader()

  return (
    <>
      <FileSystemToolbar {...header} />
      <FileSystemCommandBar controller={header} />
    </>
  )
}

export function FileSystemBrowser() {
  const controller = useFileSystemBrowser()
  const { view } = controller.browser

  return (
    <div className="flex size-full min-h-0 flex-col">
      <div className="min-h-0 flex-1">
        {view === "list" ? (
          <FileSystemListView controller={controller} />
        ) : view === "grid" ? (
          <FileSystemGridView controller={controller} />
        ) : (
          <FileSystemColumnsView controller={controller} />
        )}
      </div>
      <FileSystemStatusBar browser={controller.browser} />
    </div>
  )
}

export function FileSystemPreview() {
  const {
    entry,
    renderFileActions,
    renderMetadata,
    resolveSource,
  } = useFileSystemPreview()

  return (
    <FileSystemPreviewPanel
      entry={entry}
      renderFileActions={renderFileActions}
      renderMetadata={renderMetadata}
      resolveFileSource={resolveSource}
      className="size-full border-l-0"
    />
  )
}

"use client"

import type { FileSystemIndexState } from "./file-system-index-state"
import type { FileSystemLoadingController } from "./file-system-loading-controller"
import type { FileSystemNavigationController } from "./file-system-navigation-controller"
import type { FileSystemQueryController } from "./file-system-query-controller"
import type { FileSystemSelectionController } from "./file-system-selection-controller"
import type { FileSystemSourceController } from "./file-system-source-controller"
import type {
  FileSystemEntry,
  FileSystemIndex,
  FileSystemQueryState,
  FileSystemSortKey,
  FileSystemView,
} from "./file-system-types"
import type { FileSystemViewController } from "./file-system-view-controller"

export type FileSystemBrowserState = {
  currentPath: string
  entries: FileSystemEntry[]
  index: FileSystemIndex
  loading: FileSystemBrowserLoadingState
  navigation: FileSystemBrowserNavigationState
  query: FileSystemQueryState
  rawIndex: FileSystemIndex
  selection: FileSystemBrowserSelectionState
  commands: FileSystemBrowserCommands
  view: FileSystemView
}

export type FileSystemBrowserSelectionState = {
  selectedEntry: FileSystemEntry | null
  selectedPath: string | null
}

export type FileSystemBrowserLoadingState = {
  folderErrors: ReadonlyMap<string, string>
  loadingFolders: ReadonlySet<string>
}

export type FileSystemBrowserNavigationState = {
  canGoBack: boolean
  canGoForward: boolean
}

export type FileSystemBrowserCommands = {
  ensureChildren: FileSystemLoadingController["ensureChildren"]
  goBack: () => void
  goForward: () => void
  navigateTo: (path: string) => void
  selectEntry: (entry: FileSystemEntry | null) => void
  selectFirstChildAfterEnsure: (path: string) => Promise<FileSystemEntry | null>
  setSearch: (search: string) => void
  setSortKey: (key: FileSystemSortKey) => void
  setView: (view: FileSystemView) => void
}

export type FileSystemHeaderState = {
  canGoBack: boolean
  canGoForward: boolean
  currentPath: string
  goBack: () => void
  goForward: () => void
  query: FileSystemQueryState
  setSearch: (search: string) => void
  setSortKey: (key: FileSystemSortKey) => void
  setView: (view: FileSystemView) => void
  title: string
  view: FileSystemView
}

export type FileSystemPreviewState = {
  entry: FileSystemEntry | null
  resolveSource: FileSystemSourceController["resolveFileSource"]
}

export function createFileSystemBrowserState({
  index,
  loading,
  navigation,
  query,
  selection,
  view,
}: {
  index: FileSystemIndexState
  loading: FileSystemLoadingController
  navigation: FileSystemNavigationController
  query: FileSystemQueryController
  selection: FileSystemSelectionController
  view: FileSystemViewController
}): FileSystemBrowserState {
  return {
    currentPath: navigation.currentPath,
    entries: index.currentEntries,
    index: index.index,
    loading: {
      folderErrors: loading.folderErrors,
      loadingFolders: loading.loadingFolders,
    },
    navigation: {
      canGoBack: navigation.canGoBack,
      canGoForward: navigation.canGoForward,
    },
    query: query.query,
    rawIndex: index.rawIndex,
    selection: {
      selectedEntry: selection.selectedEntry,
      selectedPath: selection.selectedPath,
    },
    commands: {
      ensureChildren: loading.ensureChildren,
      goBack: navigation.goBack,
      goForward: navigation.goForward,
      navigateTo: navigation.navigateTo,
      selectEntry: selection.selectEntry,
      selectFirstChildAfterEnsure: selection.selectFirstChildAfterEnsure,
      setSearch: query.setSearch,
      setSortKey: query.setSortKey,
      setView: view.setView,
    },
    view: view.view,
  }
}

export function createFileSystemHeaderState({
  browser,
  title,
}: {
  browser: FileSystemBrowserState
  title: string
}): FileSystemHeaderState {
  return {
    canGoBack: browser.navigation.canGoBack,
    canGoForward: browser.navigation.canGoForward,
    currentPath: browser.currentPath,
    goBack: browser.commands.goBack,
    goForward: browser.commands.goForward,
    query: browser.query,
    setSearch: browser.commands.setSearch,
    setSortKey: browser.commands.setSortKey,
    setView: browser.commands.setView,
    title,
    view: browser.view,
  }
}

export function createFileSystemPreviewState({
  selection,
  source,
}: {
  selection: FileSystemSelectionController
  source: FileSystemSourceController
}): FileSystemPreviewState {
  return {
    entry: selection.selectedEntry,
    resolveSource: source.resolveFileSource,
  }
}

"use client"

import type { FileSystemBrowserState } from "./file-system-browser-state"
import type { FileSystemSourceController } from "./file-system-source-controller"
import type { FileSystemFileEntry } from "./file-system-types"

export type FileSystemOpenPreviewCommand = (file: FileSystemFileEntry) => void

export type FileSystemFileActionController = {
  openPreview: FileSystemOpenPreviewCommand
  resolveFileSource: FileSystemSourceController["resolveFileSource"]
}

export type FileSystemBrowserController = {
  browser: FileSystemBrowserState
  fileActions: FileSystemFileActionController
}

export function createFileSystemBrowserController({
  browser,
  openPreview,
  resolveFileSource,
}: {
  browser: FileSystemBrowserState
  openPreview: FileSystemOpenPreviewCommand
  resolveFileSource: FileSystemSourceController["resolveFileSource"]
}): FileSystemBrowserController {
  return {
    browser,
    fileActions: {
      openPreview,
      resolveFileSource,
    },
  }
}

"use client"

import * as React from "react"

import type { ViewerSource } from "@/lib/viewer-source"

import type { FileSystemSourceController } from "./file-system-source-controller"
import type { FileSystemFileEntry, FileSystemProps } from "./file-system-types"

export type FileSystemOpenPreviewState =
  | { status: "idle" }
  | { file: FileSystemFileEntry; status: "resolving" }
  | { file: FileSystemFileEntry; source: ViewerSource; status: "open" }
  | { file: FileSystemFileEntry; status: "unavailable" }
  | { error: string; file: FileSystemFileEntry; status: "failed" }

export type FileSystemOpenPreviewController = {
  close: () => void
  open: (file: FileSystemFileEntry) => void
  state: FileSystemOpenPreviewState
}

export function useFileSystemOpenPreviewController({
  onFileOpen,
  resolveFileSource,
}: {
  onFileOpen?: FileSystemProps["onFileOpen"]
  resolveFileSource: FileSystemSourceController["resolveFileSource"]
}): FileSystemOpenPreviewController {
  const [state, setState] = React.useState<FileSystemOpenPreviewState>({
    status: "idle",
  })
  const requestRef = React.useRef<{
    abortController: AbortController
    requestId: number
  } | null>(null)
  const nextRequestId = React.useRef(0)

  const close = React.useCallback(() => {
    requestRef.current?.abortController.abort()
    requestRef.current = null
    setState({ status: "idle" })
  }, [])

  const open = React.useCallback(
    (file: FileSystemFileEntry) => {
      requestRef.current?.abortController.abort()

      const requestId = nextRequestId.current + 1
      nextRequestId.current = requestId

      const abortController = new AbortController()
      requestRef.current = { abortController, requestId }
      setState({ file, status: "resolving" })

      void resolveFileSource(file, abortController.signal)
        .then((source) => {
          if (requestRef.current?.requestId !== requestId) return
          if (abortController.signal.aborted) return

          onFileOpen?.(file, source)

          if (!source) {
            setState({ file, status: "unavailable" })
            return
          }

          setState({ file, source, status: "open" })
        })
        .catch((error: unknown) => {
          if (requestRef.current?.requestId !== requestId) return
          if (abortController.signal.aborted) return

          onFileOpen?.(file, null)
          setState({
            error: fileSystemOpenPreviewErrorMessage(error),
            file,
            status: "failed",
          })
        })
    },
    [onFileOpen, resolveFileSource]
  )

  React.useEffect(() => close, [close])

  return React.useMemo(() => ({ close, open, state }), [close, open, state])
}

function fileSystemOpenPreviewErrorMessage(error: unknown) {
  return error instanceof Error && error.message
    ? error.message
    : "Unable to open file."
}

"use client"

import * as React from "react"
import { AlertCircle, ExternalLink, FileQuestion } from "lucide-react"

import type { ViewerSource } from "@/lib/viewer-source"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { FileViewer } from "@/components/ui/file-viewer"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Spinner } from "@/components/ui/spinner"

import { useFileSystem } from "./file-system-provider"
import type { FileSystemOpenPreviewState } from "./file-system-open-preview-state"

export function useFileSystemOpenPreview() {
  return useFileSystem().openPreview
}

export function FileSystemOpenPreview() {
  const { close, state } = useFileSystemOpenPreview()
  const file = state.status === "idle" ? null : state.file
  const source = state.status === "open" ? state.source : null

  return (
    <Dialog
      open={state.status !== "idle"}
      onOpenChange={(open) => {
        if (!open) close()
      }}
    >
      {file ? (
        <DialogContent className="h-[88vh] max-w-[min(96vw,1280px)] overflow-hidden p-0">
          <DialogHeader className="shrink-0 border-b px-4 py-3">
            <div className="flex min-w-0 items-center gap-3 pr-8">
              <DialogTitle className="truncate text-base">
                {file.name}
              </DialogTitle>
              {source?.kind === "url" ? (
                <Button
                  render={
                    <a href={source.url} target="_blank" rel="noreferrer" />
                  }
                  size="xs"
                  variant="outline"
                >
                  <ExternalLink className="size-3.5" aria-hidden />
                  Open
                </Button>
              ) : null}
            </div>
          </DialogHeader>
          <div className="min-h-0 flex-1">
            <FileSystemOpenPreviewContent state={state} />
          </div>
        </DialogContent>
      ) : null}
    </Dialog>
  )
}

function FileSystemOpenPreviewContent({
  state,
}: {
  state: FileSystemOpenPreviewState
}) {
  if (state.status === "resolving") {
    return (
      <FileSystemOpenPreviewMessage>
        <Spinner className="size-4" />
        Opening preview
      </FileSystemOpenPreviewMessage>
    )
  }

  if (state.status === "unavailable") {
    return (
      <FileSystemOpenPreviewMessage>
        <FileQuestion className="size-5" aria-hidden />
        Preview unavailable
      </FileSystemOpenPreviewMessage>
    )
  }

  if (state.status === "failed") {
    return (
      <FileSystemOpenPreviewMessage>
        <AlertCircle className="size-5" aria-hidden />
        {state.error}
      </FileSystemOpenPreviewMessage>
    )
  }

  if (state.status !== "open") {
    return null
  }

  return (
    <ScrollArea>
      <div className="h-[calc(88vh-4rem)] min-h-0">
        <FileSystemOpenPreviewViewer source={state.source} />
      </div>
    </ScrollArea>
  )
}

function FileSystemOpenPreviewMessage({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <div className="flex size-full items-center justify-center gap-2 text-sm text-muted-foreground">
      {children}
    </div>
  )
}

function FileSystemOpenPreviewViewer({ source }: { source: ViewerSource }) {
  return <FileViewer source={source} bare className="size-full min-h-0" />
}

"use client"

import * as React from "react"
import { PanelLeft, PanelRight } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button, type ButtonProps } from "@/components/ui/button"

export type ViewerRootProps = React.ComponentProps<"div"> & {
  bare?: boolean
  defaultSidebarOpen?: boolean
  sidebarOpen?: boolean
  onSidebarOpenChange?: (open: boolean) => void
  sidebarMode?: ViewerSidebarRequestedMode
  sidebarInlineBreakpoint?: number
}

export type ViewerSidebarMode = "inline" | "overlay"
export type ViewerSidebarRequestedMode = "auto" | ViewerSidebarMode
export type ViewerSidebarState = "expanded" | "collapsed"
export type ViewerSidebarContextValue = {
  state: ViewerSidebarState
  open: boolean
  setOpen: (value: boolean | ((open: boolean) => boolean)) => void
  toggleSidebar: () => void
  canToggleSidebar: boolean
  mode: ViewerSidebarMode
  sidebarId: string
}

type ViewerSidebarSide = "left" | "right"
type ViewerSidebarCollapsible = "offcanvas" | "none"
type ViewerSidebarRegistration = {
  collapsible: ViewerSidebarCollapsible
  element: HTMLElement
  id: string
  instanceId: string
  side: ViewerSidebarSide
  width: string
}

type ViewerSidebarRegistrationContextValue = {
  hasSidebar: boolean
  sidebarState: ViewerSidebarContextValue
  registerSidebar: (registration: ViewerSidebarRegistration) => () => void
  rootId: string
  sidebarSide: ViewerSidebarSide
  setLastTriggerElement: (element: HTMLElement | null) => void
}

const VIEWER_SIDEBAR_INLINE_BREAKPOINT = 768
const VIEWER_SIDEBAR_MODE_HYSTERESIS = 16
const VIEWER_SIDEBAR_WIDTH = "10rem"

const ViewerSidebarStateContext =
  React.createContext<ViewerSidebarContextValue | null>(null)
const ViewerSidebarRegistrationContext =
  React.createContext<ViewerSidebarRegistrationContextValue | null>(null)

function resolveSidebarMode({
  requestedMode,
  width,
  inlineBreakpoint,
}: {
  requestedMode: ViewerSidebarRequestedMode
  width: number | null
  inlineBreakpoint: number
}): ViewerSidebarMode {
  if (requestedMode !== "auto") return requestedMode
  if (width === null) return "overlay"
  return width >= inlineBreakpoint ? "inline" : "overlay"
}

function resolveMeasuredSidebarMode({
  currentMode,
  hasMeasured,
  inlineBreakpoint,
  requestedMode,
  width,
}: {
  currentMode: ViewerSidebarMode
  hasMeasured: boolean
  inlineBreakpoint: number
  requestedMode: ViewerSidebarRequestedMode
  width: number
}): ViewerSidebarMode {
  if (requestedMode !== "auto") return requestedMode
  if (!hasMeasured) {
    return width >= inlineBreakpoint ? "inline" : "overlay"
  }

  if (currentMode === "inline") {
    return width < inlineBreakpoint - VIEWER_SIDEBAR_MODE_HYSTERESIS
      ? "overlay"
      : "inline"
  }

  return width > inlineBreakpoint + VIEWER_SIDEBAR_MODE_HYSTERESIS
    ? "inline"
    : "overlay"
}

function useIsoLayoutEffect(
  effect: React.EffectCallback,
  deps: React.DependencyList
) {
  const useEffect =
    typeof window === "undefined" ? React.useEffect : React.useLayoutEffect
  useEffect(effect, deps)
}

function isAriaDisabled(value: unknown): boolean {
  return value === true || value === "true"
}

export function useViewerSidebar(): ViewerSidebarContextValue {
  const context = React.useContext(ViewerSidebarStateContext)
  if (!context) {
    throw new Error("useViewerSidebar must be used within a ViewerRoot.")
  }
  return context
}

export function useOptionalViewerSidebar(): ViewerSidebarContextValue | null {
  return React.useContext(ViewerSidebarStateContext)
}

function useViewerSidebarRegistrationContext(
  consumer: string
): ViewerSidebarRegistrationContextValue {
  const context = React.useContext(ViewerSidebarRegistrationContext)
  if (!context) {
    throw new Error(`${consumer} must be used within a ViewerRoot.`)
  }
  return context
}

export function ViewerRoot({
  bare = false,
  className,
  style,
  defaultSidebarOpen = false,
  sidebarOpen: sidebarOpenProp,
  onSidebarOpenChange,
  sidebarMode = "auto",
  sidebarInlineBreakpoint = VIEWER_SIDEBAR_INLINE_BREAKPOINT,
  ...props
}: ViewerRootProps) {
  const rootRef = React.useRef<HTMLDivElement | null>(null)
  const reactId = React.useId()
  const rootId = `${reactId}-viewer-root`
  const fallbackSidebarId = `${reactId}-viewer-sidebar`
  const isControlled = sidebarOpenProp !== undefined
  const [internalOpen, setInternalOpen] = React.useState(defaultSidebarOpen)
  const open = sidebarOpenProp ?? internalOpen
  const openRef = React.useRef(open)
  const hasMeasuredSidebarWidthRef = React.useRef(false)
  const lastTriggerElementRef = React.useRef<HTMLElement | null>(null)
  const registeredSidebarRef = React.useRef<ViewerSidebarRegistration | null>(
    null
  )
  const [registeredSidebar, setRegisteredSidebar] =
    React.useState<ViewerSidebarRegistration | null>(null)
  const [resolvedSidebarMode, setResolvedSidebarMode] =
    React.useState<ViewerSidebarMode>(() =>
      resolveSidebarMode({
        requestedMode: sidebarMode,
        width: null,
        inlineBreakpoint: sidebarInlineBreakpoint,
      })
    )

  React.useEffect(() => {
    openRef.current = open
  }, [open])

  React.useEffect(() => {
    if (sidebarMode === "auto") return
    setResolvedSidebarMode((currentMode) => {
      const nextMode = sidebarMode
      return currentMode === nextMode ? currentMode : nextMode
    })
  }, [sidebarMode])

  useIsoLayoutEffect(() => {
    const element = rootRef.current
    const ResizeObserverConstructor = globalThis.ResizeObserver
    if (!element || typeof ResizeObserverConstructor === "undefined") return
    if (sidebarMode !== "auto") {
      setResolvedSidebarMode(sidebarMode)
      return
    }

    const updateMode = () => {
      const nextWidth = element.getBoundingClientRect().width
      if (nextWidth === 0) return

      setResolvedSidebarMode((currentMode) => {
        const nextMode = resolveMeasuredSidebarMode({
          currentMode,
          hasMeasured: hasMeasuredSidebarWidthRef.current,
          requestedMode: sidebarMode,
          width: nextWidth,
          inlineBreakpoint: sidebarInlineBreakpoint,
        })

        hasMeasuredSidebarWidthRef.current = true
        return currentMode === nextMode ? currentMode : nextMode
      })
    }

    updateMode()

    const observer = new ResizeObserverConstructor(updateMode)
    observer.observe(element)

    return () => observer.disconnect()
  }, [sidebarInlineBreakpoint, sidebarMode])

  const setOpen = React.useCallback(
    (value: boolean | ((open: boolean) => boolean)) => {
      const previousOpen = isControlled ? open : openRef.current
      const nextOpen = typeof value === "function" ? value(previousOpen) : value

      if (nextOpen === previousOpen) {
        return
      }

      if (!isControlled) {
        openRef.current = nextOpen
        setInternalOpen(nextOpen)
      }
      onSidebarOpenChange?.(nextOpen)
    },
    [isControlled, onSidebarOpenChange, open]
  )

  const registerSidebar = React.useCallback(
    (registration: ViewerSidebarRegistration) => {
      const currentRegistration = registeredSidebarRef.current

      if (
        currentRegistration &&
        currentRegistration.instanceId !== registration.instanceId
      ) {
        throw new Error(
          "ViewerRoot supports one primary ViewerSidebar. Use a nested ViewerRoot for a complete nested viewer, or put secondary content inside ViewerSurface."
        )
      }

      registeredSidebarRef.current = registration
      setRegisteredSidebar(registration)

      return () => {
        if (
          registeredSidebarRef.current?.instanceId !== registration.instanceId
        ) {
          return
        }

        registeredSidebarRef.current = null
        setRegisteredSidebar(null)
      }
    },
    []
  )

  const toggleSidebar = React.useCallback(() => {
    setOpen((currentOpen) => !currentOpen)
  }, [setOpen])

  const hasSidebar = registeredSidebar !== null
  const effectiveOpen = registeredSidebar?.collapsible === "none" ? true : open
  const state: ViewerSidebarState = effectiveOpen ? "expanded" : "collapsed"
  const canToggleSidebar =
    hasSidebar && registeredSidebar.collapsible !== "none"
  const sidebarId = registeredSidebar?.id ?? fallbackSidebarId
  const sidebarSide = registeredSidebar?.side ?? "left"
  const sidebarWidth = registeredSidebar?.width ?? VIEWER_SIDEBAR_WIDTH
  const setLastTriggerElement = React.useCallback(
    (element: HTMLElement | null) => {
      lastTriggerElementRef.current = element
    },
    []
  )

  React.useEffect(() => {
    if (
      !open ||
      !canToggleSidebar ||
      resolvedSidebarMode !== "overlay" ||
      typeof document === "undefined"
    ) {
      return
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false)
        const triggerElement =
          lastTriggerElementRef.current?.isConnected === true
            ? lastTriggerElementRef.current
            : rootRef.current?.querySelector<HTMLElement>(
                "[data-viewer-sidebar-trigger]"
              )
        triggerElement?.focus()
      }
    }
    const handlePointerDown = (event: PointerEvent) => {
      const target = event.target

      if (
        target instanceof Node &&
        registeredSidebar?.element.contains(target)
      ) {
        return
      }

      if (target instanceof Element) {
        const triggerElement = target.closest<HTMLElement>(
          "[data-viewer-sidebar-trigger]"
        )
        if (triggerElement?.dataset.viewerRootId === rootId) {
          return
        }
      }

      setOpen(false)
    }

    document.addEventListener("keydown", handleKeyDown)
    document.addEventListener("pointerdown", handlePointerDown)

    return () => {
      document.removeEventListener("keydown", handleKeyDown)
      document.removeEventListener("pointerdown", handlePointerDown)
    }
  }, [
    canToggleSidebar,
    open,
    registeredSidebar,
    resolvedSidebarMode,
    rootId,
    setOpen,
  ])

  const sidebarStateContext = React.useMemo<ViewerSidebarContextValue>(
    () => ({
      state,
      open: effectiveOpen,
      setOpen,
      toggleSidebar,
      canToggleSidebar,
      mode: resolvedSidebarMode,
      sidebarId,
    }),
    [
      state,
      effectiveOpen,
      setOpen,
      toggleSidebar,
      canToggleSidebar,
      resolvedSidebarMode,
      sidebarId,
    ]
  )

  const sidebarRegistrationContext =
    React.useMemo<ViewerSidebarRegistrationContextValue>(
      () => ({
        hasSidebar,
        sidebarState: sidebarStateContext,
        registerSidebar,
        rootId,
        sidebarSide,
        setLastTriggerElement,
      }),
      [
        hasSidebar,
        sidebarStateContext,
        registerSidebar,
        rootId,
        sidebarSide,
        setLastTriggerElement,
      ]
    )

  return (
    <ViewerSidebarStateContext.Provider value={sidebarStateContext}>
      <ViewerSidebarRegistrationContext.Provider
        value={sidebarRegistrationContext}
      >
        <div
          ref={rootRef}
          data-slot="viewer-root"
          data-viewer-root-id={rootId}
          className={cn(
            "relative flex min-h-0 flex-col overflow-hidden",
            bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
            className
          )}
          style={
            {
              ...style,
              "--viewer-sidebar-width": sidebarWidth,
            } as React.CSSProperties
          }
          {...props}
        />
      </ViewerSidebarRegistrationContext.Provider>
    </ViewerSidebarStateContext.Provider>
  )
}

