"use client"

import * as React from "react"
import { useFileTree } from "@pierre/trees/react"

import type {
  FileSystemPierreDecorationState,
  FileSystemPierreLoadingController,
  FileSystemPierreNavigationController,
  FileSystemPierreQueryState,
  FileSystemPierreSelectionController,
} from "./file-system-pierre-adapter"
import {
  FILE_SYSTEM_PIERRE_ROW_CSS,
  fileSystemPierreRowDecoration,
} from "./file-system-pierre-decoration"
import {
  useBindFileSystemPierreExpansionModel,
  useFileSystemPierreExpansion,
} from "./file-system-pierre-expansion"
import type { FileSystemPierreInput } from "./file-system-pierre-input"
import { createFileSystemPierreLazyFolderCommand } from "./file-system-pierre-lazy-retry"
import { useFileSystemPierreOrder } from "./file-system-pierre-order"
import { useResetFileSystemPierreModel } from "./file-system-pierre-reset"
import {
  useFileSystemPierreSelectionHandler,
  useLatestFileSystemPierreSelectionState,
  useSyncFileSystemPierreSelection,
} from "./file-system-pierre-selection"

export const FILE_SYSTEM_PIERRE_ROW_HEIGHT = 36

const INITIAL_VISIBLE_ROW_COUNT = 24
const useIsoLayoutEffect =
  typeof window === "undefined" ? React.useEffect : React.useLayoutEffect

export function useFileSystemPierreModel({
  decoration,
  decorationVersion,
  input,
  loading,
  navigation,
  query,
  selection,
}: {
  decoration: FileSystemPierreDecorationState
  decorationVersion: string
  input: FileSystemPierreInput
  loading: FileSystemPierreLoadingController
  navigation: FileSystemPierreNavigationController
  query: FileSystemPierreQueryState
  selection: FileSystemPierreSelectionController
}) {
  const decorationRef = React.useRef(decoration)
  const loadingRef = React.useRef(loading)
  const hasSemanticQuery = query.search.length > 0
  const order = useFileSystemPierreOrder(input.pierrePaths)
  const expansion = useFileSystemPierreExpansion({ loading })
  const getLatestSelectionState = useLatestFileSystemPierreSelectionState({
    input,
    selection,
  })
  const handleSelectionChange = useFileSystemPierreSelectionHandler(
    getLatestSelectionState
  )

  useIsoLayoutEffect(() => {
    decorationRef.current = decoration
    loadingRef.current = loading
  }, [decoration, loading])

  const initialSelectedPaths = React.useMemo(() => {
    const selected = input.pierrePaths.find(
      (pierrePath) =>
        input.entriesByPierrePath.get(pierrePath)?.path ===
        selection.selectedPath
    )

    return selected ? [selected] : []
  }, [input, selection.selectedPath])

  const { model } = useFileTree({
    flattenEmptyDirectories: false,
    icons: { colored: false, set: "complete" },
    initialExpansion: hasSemanticQuery ? "open" : "closed",
    initialSelectedPaths,
    initialVisibleRowCount: INITIAL_VISIBLE_ROW_COUNT,
    itemHeight: FILE_SYSTEM_PIERRE_ROW_HEIGHT,
    onSelectionChange: (selectedPaths) => {
      const selected = handleSelectionChange(selectedPaths)
      const currentLoading = loadingRef.current
      const command = createFileSystemPierreLazyFolderCommand({
        folderErrors: currentLoading.folderErrors,
        selection: selected,
      })

      expansion.runLazyFolderCommand(command)
    },
    overscan: 12,
    paths: input.pierrePaths,
    preparedInput: input.preparedInput,
    renderRowDecoration: ({ item }) => {
      const { input } = getLatestSelectionState()
      const entry = input.entriesByPierrePath.get(item.path)

      return entry
        ? fileSystemPierreRowDecoration(entry, decorationRef.current)
        : null
    },
    search: false,
    sort: order.compare,
    stickyFolders: false,
    unsafeCSS: FILE_SYSTEM_PIERRE_ROW_CSS,
  })

  useResetFileSystemPierreModel({
    currentPath: navigation.currentPath,
    decorationVersion,
    expansion,
    hasSemanticQuery,
    input,
    model,
    order,
    selectedPath: selection.selectedPath,
  })
  useSyncFileSystemPierreSelection({ input, model, selection })
  useBindFileSystemPierreExpansionModel({ expansion, model })
  useRepaintFileSystemPierreDecoration({ decorationVersion, model })

  return { model }
}

function useRepaintFileSystemPierreDecoration({
  decorationVersion,
  model,
}: {
  decorationVersion: string
  model: ReturnType<typeof useFileTree>["model"]
}) {
  useIsoLayoutEffect(() => {
    if (!model.getFileTreeContainer()) {
      return
    }

    model.render({})
  }, [decorationVersion, model])
}

"use client"

import * as React from "react"
import type { FileTree as PierreFileTreeModel } from "@pierre/trees"

import type { FileSystemPierreExpansion } from "./file-system-pierre-expansion"
import type { FileSystemPierreInput } from "./file-system-pierre-input"
import type { FileSystemPierreOrder } from "./file-system-pierre-order"
import {
  classifyFileSystemPierreResetTransition,
  createFileSystemPierreResetIdentity,
} from "./file-system-pierre-reset-identity"
import { scrollCurrentFileSystemEntryIntoView } from "./file-system-pierre-selection"

const useIsoLayoutEffect =
  typeof window === "undefined" ? React.useEffect : React.useLayoutEffect

export function useResetFileSystemPierreModel({
  currentPath,
  decorationVersion,
  expansion,
  hasSemanticQuery,
  input,
  model,
  order,
  selectedPath,
}: {
  currentPath: string
  decorationVersion: string
  expansion: FileSystemPierreExpansion
  hasSemanticQuery: boolean
  input: FileSystemPierreInput
  model: PierreFileTreeModel
  order: FileSystemPierreOrder
  selectedPath: string | null
}) {
  const appliedIdentityRef = React.useRef(
    createFileSystemPierreResetIdentity({
      currentPath,
      decorationVersion,
      hasSemanticQuery,
      input,
    })
  )

  useIsoLayoutEffect(() => {
    const previousIdentity = appliedIdentityRef.current
    const nextIdentity = createFileSystemPierreResetIdentity({
      currentPath,
      decorationVersion,
      hasSemanticQuery,
      input,
    })

    const transition = classifyFileSystemPierreResetTransition(
      previousIdentity,
      nextIdentity
    )
    const plan = expansion.createResetPlan(transition)

    if (plan.kind === "none") {
      return
    }

    expansion.rememberBeforeReset(plan.transition.previous)
    appliedIdentityRef.current = nextIdentity
    order.reset(plan.nextPierrePaths)
    model.resetPaths(plan.nextPierrePaths, {
      initialExpandedPaths: plan.initialExpandedPaths,
      preparedInput: plan.transition.next.input.preparedInput,
    })
    scrollCurrentFileSystemEntryIntoView({
      input: plan.transition.next.input,
      model,
      selectedPath,
    })
  }, [
    currentPath,
    decorationVersion,
    expansion,
    hasSemanticQuery,
    input,
    model,
    order,
    selectedPath,
  ])
}

import type { FileSystemPierreInput } from "./file-system-pierre-input"

export type FileSystemPierreResetIdentity = {
  currentPath: string
  decorationVersion: string
  hasSemanticQuery: boolean
  input: FileSystemPierreInput
}

export type FileSystemPierreResetDiff = {
  didChangeCurrentPath: boolean
  didChangeDecoration: boolean
  didChangeInput: boolean
  didChangeSemanticQuery: boolean
}

export type FileSystemPierreResetTransition =
  | {
      identity: FileSystemPierreResetIdentity
      kind: "same"
    }
  | {
      kind:
        | "decoration"
        | "input"
        | "path"
        | "query-enter"
        | "query-exit"
        | "query-update"
      next: FileSystemPierreResetIdentity
      previous: FileSystemPierreResetIdentity
    }

export function createFileSystemPierreResetIdentity({
  currentPath,
  decorationVersion,
  hasSemanticQuery,
  input,
}: {
  currentPath: string
  decorationVersion: string
  hasSemanticQuery: boolean
  input: FileSystemPierreInput
}): FileSystemPierreResetIdentity {
  return {
    currentPath,
    decorationVersion,
    hasSemanticQuery,
    input,
  }
}

export function diffFileSystemPierreResetIdentity(
  previous: FileSystemPierreResetIdentity,
  next: FileSystemPierreResetIdentity
): FileSystemPierreResetDiff {
  return {
    didChangeCurrentPath: previous.currentPath !== next.currentPath,
    didChangeDecoration: previous.decorationVersion !== next.decorationVersion,
    didChangeInput: previous.input !== next.input,
    didChangeSemanticQuery: previous.hasSemanticQuery !== next.hasSemanticQuery,
  }
}

export function classifyFileSystemPierreResetTransition(
  previous: FileSystemPierreResetIdentity,
  next: FileSystemPierreResetIdentity
): FileSystemPierreResetTransition {
  const diff = diffFileSystemPierreResetIdentity(previous, next)

  if (
    !diff.didChangeCurrentPath &&
    !diff.didChangeDecoration &&
    !diff.didChangeInput &&
    !diff.didChangeSemanticQuery
  ) {
    return { identity: next, kind: "same" }
  }

  if (diff.didChangeCurrentPath) {
    return { kind: "path", previous, next }
  }

  if (!previous.hasSemanticQuery && next.hasSemanticQuery) {
    return { kind: "query-enter", previous, next }
  }

  if (previous.hasSemanticQuery && next.hasSemanticQuery) {
    return { kind: "query-update", previous, next }
  }

  if (previous.hasSemanticQuery && !next.hasSemanticQuery) {
    return { kind: "query-exit", previous, next }
  }

  if (diff.didChangeDecoration) {
    return { kind: "decoration", previous, next }
  }

  return { kind: "input", previous, next }
}

import type { FileSystemPierreExpansionSnapshot } from "./file-system-pierre-expansion-snapshot"
import {
  collectFileSystemPierreDirectoryPaths,
  filterFileSystemPierreExpandedPaths,
} from "./file-system-pierre-expansion-snapshot"
import type { PierrePath } from "./file-system-pierre-input"
import type { FileSystemPierreResetTransition } from "./file-system-pierre-reset-identity"

export type FileSystemPierreResetPlan =
  | {
      kind: "none"
    }
  | {
      initialExpandedPaths: PierrePath[]
      kind: "reset"
      nextPierrePaths: PierrePath[]
      transition: Exclude<FileSystemPierreResetTransition, { kind: "same" }>
    }

export function createFileSystemPierreResetPlan({
  snapshotsByCurrentPath,
  transition,
}: {
  snapshotsByCurrentPath: ReadonlyMap<string, FileSystemPierreExpansionSnapshot>
  transition: FileSystemPierreResetTransition
}): FileSystemPierreResetPlan {
  if (transition.kind === "same") {
    return { kind: "none" }
  }

  return {
    initialExpandedPaths: resolveFileSystemPierreInitialExpansion({
      snapshotsByCurrentPath,
      transition,
    }),
    kind: "reset",
    nextPierrePaths: transition.next.input.pierrePaths,
    transition,
  }
}

export function resolveFileSystemPierreInitialExpansion({
  snapshotsByCurrentPath,
  transition,
}: {
  snapshotsByCurrentPath: ReadonlyMap<string, FileSystemPierreExpansionSnapshot>
  transition: Exclude<FileSystemPierreResetTransition, { kind: "same" }>
}): PierrePath[] {
  switch (transition.kind) {
    case "query-enter":
    case "query-update":
      return collectFileSystemPierreDirectoryPaths(
        transition.next.input.pierrePaths
      )
    case "decoration":
    case "input":
    case "path":
    case "query-exit":
      return restoreFileSystemPierreNormalExpansion({
        currentPath: transition.next.currentPath,
        nextPierrePaths: transition.next.input.pierrePaths,
        snapshotsByCurrentPath,
      })
  }
}

function restoreFileSystemPierreNormalExpansion({
  currentPath,
  nextPierrePaths,
  snapshotsByCurrentPath,
}: {
  currentPath: string
  nextPierrePaths: readonly PierrePath[]
  snapshotsByCurrentPath: ReadonlyMap<string, FileSystemPierreExpansionSnapshot>
}): PierrePath[] {
  const snapshot = snapshotsByCurrentPath.get(currentPath)

  return filterFileSystemPierreExpandedPaths({
    expandedPierrePaths: snapshot?.expandedPierrePaths ?? new Set(),
    nextPierrePaths,
  })
}

