import * as React from "react"
import type { FileTree as PierreFileTreeModel } from "@pierre/trees"

import type { FileSystemPierreLoadingController } from "./file-system-pierre-adapter"
import {
  rememberFileSystemPierreExpansionSnapshot,
  resolveFileSystemPierreExpansionAfterReset,
  type FileSystemPierreExpansionSnapshot,
} from "./file-system-pierre-expansion-snapshot"
import type { PierrePath } from "./file-system-pierre-input"
import {
  useFileSystemPierreLazyRetryExpansion,
  type FileSystemPierreLazyFolderCommand,
} from "./file-system-pierre-lazy-retry"
import type {
  FileSystemPierreResetIdentity,
  FileSystemPierreResetTransition,
} from "./file-system-pierre-reset-identity"
import {
  createFileSystemPierreResetPlan,
  type FileSystemPierreResetPlan,
} from "./file-system-pierre-reset-plan"

const useIsoLayoutEffect =
  typeof window === "undefined" ? React.useEffect : React.useLayoutEffect

export type FileSystemPierreExpansion = {
  createResetPlan: (
    transition: FileSystemPierreResetTransition
  ) => FileSystemPierreResetPlan
  runLazyFolderCommand: (
    command: FileSystemPierreLazyFolderCommand | null
  ) => void
  modelRef: React.MutableRefObject<PierreFileTreeModel | null>
  rememberBeforeReset: (identity: FileSystemPierreResetIdentity) => void
  resolveAfterReset: (identity: FileSystemPierreResetIdentity) => PierrePath[]
}

export function useFileSystemPierreExpansion({
  loading,
}: {
  loading: FileSystemPierreLoadingController
}): FileSystemPierreExpansion {
  const modelRef = React.useRef<PierreFileTreeModel | null>(null)
  const snapshotsByCurrentPathRef = React.useRef(
    new Map<string, FileSystemPierreExpansionSnapshot>()
  )
  const runLazyFolderCommand = useFileSystemPierreLazyRetryExpansion({
    loading,
    modelRef,
  })
  const createResetPlan = React.useCallback(
    (transition: FileSystemPierreResetTransition) =>
      createFileSystemPierreResetPlan({
        snapshotsByCurrentPath: snapshotsByCurrentPathRef.current,
        transition,
      }),
    []
  )
  const rememberBeforeReset = React.useCallback(
    (identity: FileSystemPierreResetIdentity) => {
      const model = modelRef.current

      if (!model) {
        return
      }

      rememberFileSystemPierreExpansionSnapshot({
        identity,
        model,
        snapshotsByCurrentPath: snapshotsByCurrentPathRef.current,
      })
    },
    []
  )
  const resolveAfterReset = React.useCallback(
    (identity: FileSystemPierreResetIdentity) =>
      resolveFileSystemPierreExpansionAfterReset({
        identity,
        snapshotsByCurrentPath: snapshotsByCurrentPathRef.current,
      }),
    []
  )

  return React.useMemo(
    () => ({
      createResetPlan,
      modelRef,
      rememberBeforeReset,
      resolveAfterReset,
      runLazyFolderCommand,
    }),
    [
      createResetPlan,
      rememberBeforeReset,
      resolveAfterReset,
      runLazyFolderCommand,
    ]
  )
}

export function useBindFileSystemPierreExpansionModel({
  expansion,
  model,
}: {
  expansion: FileSystemPierreExpansion
  model: PierreFileTreeModel
}) {
  useIsoLayoutEffect(() => {
    expansion.modelRef.current = model
    return () => {
      if (expansion.modelRef.current === model) {
        expansion.modelRef.current = null
      }
    }
  }, [expansion, model])
}

import {
  type FileTreeDirectoryHandle,
  type FileTreeItemHandle,
  type FileTree as PierreFileTreeModel,
} from "@pierre/trees"

import type { PierrePath } from "./file-system-pierre-input"
import type { FileSystemPierreResetIdentity } from "./file-system-pierre-reset-identity"

export type FileSystemPierreExpansionSnapshot = {
  expandedPierrePaths: Set<PierrePath>
  mode: "normal" | "query"
}

export function rememberFileSystemPierreExpansionSnapshot({
  identity,
  model,
  snapshotsByCurrentPath,
}: {
  identity: FileSystemPierreResetIdentity
  model: PierreFileTreeModel
  snapshotsByCurrentPath: Map<string, FileSystemPierreExpansionSnapshot>
}) {
  const previous = snapshotsByCurrentPath.get(identity.currentPath)
  const mode = identity.hasSemanticQuery ? "query" : "normal"

  if (mode === "query" && previous?.mode === "normal") {
    return
  }

  snapshotsByCurrentPath.set(identity.currentPath, {
    expandedPierrePaths: new Set(
      collectOpenPierrePaths(model, identity.input.pierrePaths)
    ),
    mode,
  })
}

export function resolveFileSystemPierreExpansionAfterReset({
  identity,
  snapshotsByCurrentPath,
}: {
  identity: FileSystemPierreResetIdentity
  snapshotsByCurrentPath: ReadonlyMap<string, FileSystemPierreExpansionSnapshot>
}): PierrePath[] {
  if (identity.hasSemanticQuery) {
    return collectFileSystemPierreDirectoryPaths(identity.input.pierrePaths)
  }

  const snapshot = snapshotsByCurrentPath.get(identity.currentPath)

  return filterFileSystemPierreExpandedPaths({
    expandedPierrePaths: snapshot?.expandedPierrePaths ?? new Set(),
    nextPierrePaths: identity.input.pierrePaths,
  })
}

function collectOpenPierrePaths(
  model: PierreFileTreeModel,
  pierrePaths: readonly PierrePath[]
): PierrePath[] {
  const openPaths: PierrePath[] = []

  for (const path of pierrePaths) {
    const item = model.getItem(path)

    if (isDirectoryItem(item) && item.isExpanded()) {
      openPaths.push(path)
    }
  }

  return openPaths
}

export function collectFileSystemPierreDirectoryPaths(
  pierrePaths: readonly PierrePath[]
): PierrePath[] {
  return pierrePaths.filter((path) => path.endsWith("/"))
}

export function filterFileSystemPierreExpandedPaths({
  expandedPierrePaths,
  nextPierrePaths,
}: {
  expandedPierrePaths: ReadonlySet<PierrePath>
  nextPierrePaths: readonly PierrePath[]
}): PierrePath[] {
  const nextPierrePathSet = new Set(nextPierrePaths)

  return [...expandedPierrePaths].filter((path) => nextPierrePathSet.has(path))
}

function isDirectoryItem(
  item: FileTreeItemHandle | null
): item is FileTreeDirectoryHandle {
  return item?.isDirectory() === true
}

