"use client"

import * as React from "react"

import type { FileSystemBrowserState } from "./file-system-browser-state"
import {
  createFileSystemPierreAdapterState,
  type FileSystemPierreAdapterSource,
} from "./file-system-pierre-adapter"
import { useFileSystemPierreDecorationVersion } from "./file-system-pierre-decoration-version"
import {
  buildFileSystemPierreInput,
  pierrePathToFileSystemEntry,
} from "./file-system-pierre-input"
import { useFileSystemPierreModel } from "./file-system-pierre-model"
import type { FileSystemFileEntry } from "./file-system-types"

export function useFileSystemListModel({
  browser,
  openPreview,
}: {
  browser: FileSystemBrowserState
  openPreview: (entry: FileSystemFileEntry) => void
}) {
  const source = createFileSystemPierreAdapterSource(browser)
  const pierre = createFileSystemPierreAdapterState(source)
  const decorationVersion = useFileSystemPierreDecorationVersion({
    folderErrors: pierre.decoration.folderErrors,
    loadingFolders: pierre.decoration.loadingFolders,
  })
  const input = React.useMemo(
    () =>
      buildFileSystemPierreInput({
        currentPath: browser.currentPath,
        index: browser.index,
      }),
    [browser.currentPath, browser.index]
  )
  const { model } = useFileSystemPierreModel({
    decoration: pierre.decoration,
    decorationVersion,
    input,
    loading: pierre.loading,
    navigation: pierre.navigation,
    query: pierre.query,
    selection: pierre.selection,
  })
  const openPierrePath = React.useCallback(
    (path: string | null) => {
      const entry = pierrePathToFileSystemEntry(path, input)

      if (!entry) {
        return
      }

      if (entry.kind === "folder") {
        if (browser.loading.folderErrors.has(entry.path)) {
          void browser.commands.ensureChildren(entry.path, { retry: true })
        }
        browser.commands.navigateTo(entry.path)
        return
      }

      openPreview(entry)
    },
    [browser.commands, browser.loading.folderErrors, input, openPreview]
  )
  const onDoubleClick = React.useCallback(
    (event: React.MouseEvent<HTMLElement>) => {
      openPierrePath(pierrePathFromEvent(event))
    },
    [openPierrePath]
  )
  const onKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLElement>) => {
      if (event.key !== "Enter") {
        return
      }

      openPierrePath(
        model.getFocusedPath() ?? model.getSelectedPaths().at(-1) ?? null
      )
      event.preventDefault()
    },
    [model, openPierrePath]
  )

  return {
    hasRows: browser.entries.length > 0,
    model,
    onDoubleClick,
    onKeyDown,
  }
}

function createFileSystemPierreAdapterSource(
  browser: FileSystemBrowserState
): FileSystemPierreAdapterSource {
  return {
    currentPath: browser.currentPath,
    ensureChildren: browser.commands.ensureChildren,
    folderErrors: browser.loading.folderErrors,
    index: browser.index,
    loadingFolders: browser.loading.loadingFolders,
    navigateTo: browser.commands.navigateTo,
    search: browser.query.search,
    selectEntry: browser.commands.selectEntry,
    selectedPath: browser.selection.selectedPath,
  }
}

function pierrePathFromEvent(event: React.SyntheticEvent<HTMLElement>) {
  for (const target of event.nativeEvent.composedPath()) {
    if (
      target instanceof HTMLElement &&
      target.dataset.type === "item" &&
      target.dataset.itemPath
    ) {
      return target.dataset.itemPath
    }
  }

  return null
}

"use client"

import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"
import { Folder } from "lucide-react"

import { cn } from "@/lib/utils"
import { ScrollArea } from "@/components/ui/scroll-area"

import type { FileSystemBrowserController } from "./file-system-browser-controller"
import { FileSystemThumbnail } from "./file-system-preview"
import type { FileSystemEntry } from "./file-system-types"
import { useFileSystemRovingFocus } from "./use-file-system-roving-focus"

const TILE_MIN_WIDTH = 124
const TILE_HEIGHT = 132
const GRID_PADDING = 12

export function FileSystemGridView({
  controller,
}: {
  controller: FileSystemBrowserController
}) {
  const viewportRef = React.useRef<HTMLDivElement | null>(null)
  const [columnCount, setColumnCount] = React.useState(1)
  const { browser, fileActions } = controller
  const entries = browser.entries

  React.useLayoutEffect(() => {
    const viewport = viewportRef.current
    if (!viewport || typeof ResizeObserver === "undefined") return

    const update = () => {
      const available = Math.max(1, viewport.clientWidth - GRID_PADDING * 2)
      setColumnCount(Math.max(1, Math.floor(available / TILE_MIN_WIDTH)))
    }
    const observer = new ResizeObserver(update)

    update()
    observer.observe(viewport)
    return () => observer.disconnect()
  }, [])

  const rowCount = Math.ceil(entries.length / columnCount)
  const virtualizer = useVirtualizer({
    count: rowCount,
    estimateSize: () => TILE_HEIGHT,
    getScrollElement: () => viewportRef.current,
    overscan: 5,
  })
  const virtualRows = virtualizer.getVirtualItems()
  const renderedRows = virtualRows.length
    ? virtualRows.map((row) => ({ index: row.index, start: row.start }))
    : Array.from({ length: rowCount }, (_, index) => ({
        index,
        start: index * TILE_HEIGHT,
      }))
  const totalSize = virtualRows.length
    ? virtualizer.getTotalSize()
    : rowCount * TILE_HEIGHT
  const rovingFocus = useFileSystemRovingFocus({
    entries,
    getScrollIndex: (entry) => {
      const index = entries.findIndex(
        (candidate) => candidate.path === entry.path
      )

      return index === -1 ? -1 : Math.floor(index / columnCount)
    },
    onSelect: browser.commands.selectEntry,
    scrollToIndex: (index) => {
      if (index !== -1) virtualizer.scrollToIndex(index)
    },
    selectedPath: browser.selection.selectedPath,
  })
  const openEntry = React.useCallback(
    (entry: FileSystemEntry) => {
      if (entry.kind === "folder") {
        browser.commands.navigateTo(entry.path)
      } else {
        fileActions.openPreview(entry)
      }
    },
    [browser.commands, fileActions]
  )
  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "ArrowRight" || event.key === "ArrowLeft") {
      rovingFocus.selectByOffset(event.key === "ArrowRight" ? 1 : -1)
      event.preventDefault()
      return
    }
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      rovingFocus.selectByOffset(
        event.key === "ArrowDown" ? columnCount : -columnCount
      )
      event.preventDefault()
      return
    }
    if (event.key === "Home" || event.key === "End") {
      rovingFocus.selectBoundary(event.key === "Home" ? "first" : "last")
      event.preventDefault()
      return
    }
    if (event.key === "Enter" && browser.selection.selectedEntry) {
      openEntry(browser.selection.selectedEntry)
      event.preventDefault()
      return
    }

    rovingFocus.selectTypeAhead(event)
  }

  if (!entries.length) {
    return (
      <div className="flex size-full items-center justify-center text-sm text-muted-foreground">
        This folder is empty
      </div>
    )
  }

  return (
    <ScrollArea
      orientation="vertical"
      viewportRef={viewportRef}
      viewportClassName="p-3"
      viewportProps={{
        onKeyDown: handleKeyDown,
        role: "listbox",
        tabIndex: 0,
        "aria-label": "Files",
      }}
    >
      <div className="relative" style={{ height: totalSize }}>
        {renderedRows.map((row) => {
          const rowEntries = entries.slice(
            row.index * columnCount,
            row.index * columnCount + columnCount
          )

          return (
            <div
              key={row.index}
              className="absolute inset-x-0 grid gap-2"
              style={{
                gridTemplateColumns: `repeat(${columnCount}, minmax(0, 1fr))`,
                transform: `translateY(${row.start}px)`,
              }}
            >
              {rowEntries.map((entry) => (
                <FileSystemGridTile
                  key={entry.path}
                  controller={controller}
                  entry={entry}
                  ref={(element) => {
                    rovingFocus.registerEntryRef(entry.path, element)
                  }}
                />
              ))}
            </div>
          )
        })}
      </div>
    </ScrollArea>
  )
}

const FileSystemGridTile = React.forwardRef<
  HTMLButtonElement,
  {
    controller: FileSystemBrowserController
    entry: FileSystemEntry
  }
>(function FileSystemGridTile({ controller, entry }, ref) {
  const { browser, fileActions } = controller
  const selectedPath = browser.selection.selectedPath
  const isSelected = entry.path === selectedPath

  return (
    <button
      ref={ref}
      type="button"
      role="option"
      aria-selected={isSelected}
      tabIndex={isSelected || !selectedPath ? 0 : -1}
      onClick={() => browser.commands.selectEntry(entry)}
      onDoubleClick={() => {
        if (entry.kind === "folder") {
          browser.commands.navigateTo(entry.path)
        } else {
          fileActions.openPreview(entry)
        }
      }}
      className="group flex h-[124px] min-w-0 flex-col items-center gap-2 rounded-sm p-2 text-center outline-none hover:bg-accent/50 focus-visible:ring-2 focus-visible:ring-ring"
    >
      <span
        className={cn(
          "flex size-16 shrink-0 items-center justify-center rounded-sm",
          isSelected && "bg-accent"
        )}
      >
        {entry.kind === "folder" ? (
          <Folder className="size-11 text-muted-foreground" aria-hidden />
        ) : (
          <FileSystemThumbnail
            file={entry}
            resolveFileSource={fileActions.resolveFileSource}
            className="w-14"
          />
        )}
      </span>
      <span
        className={cn(
          "line-clamp-2 max-w-full rounded px-1 text-xs leading-tight break-words",
          isSelected && "bg-primary text-primary-foreground"
        )}
      >
        {entry.name}
      </span>
    </button>
  )
})

"use client"

import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"
import { ChevronRight, Folder } from "lucide-react"

import { cn } from "@/lib/utils"
import { ScrollArea } from "@/components/ui/scroll-area"

import type { FileSystemBrowserController } from "./file-system-browser-controller"
import { folderHasChildren, pathParent } from "./file-system-index"
import { FileSystemThumbnail } from "./file-system-preview"
import type { FileSystemEntry } from "./file-system-types"
import { useFileSystemRovingFocus } from "./use-file-system-roving-focus"

const COLUMN_ROW_HEIGHT = 32

export function FileSystemColumnsView({
  controller,
}: {
  controller: FileSystemBrowserController
}) {
  const { browser, fileActions } = controller
  const columnPaths = React.useMemo(() => {
    const paths = [browser.currentPath]
    const selectedPath = browser.selection.selectedPath

    if (!selectedPath?.startsWith(browser.currentPath)) return paths

    const selectedEntry = browser.selection.selectedEntry
    const targetPath =
      selectedEntry?.kind === "folder"
        ? selectedEntry.path
        : (selectedEntry?.parentPath ?? browser.currentPath)
    const relativePath = targetPath.slice(browser.currentPath.length)
    let walkedPath = browser.currentPath

    for (const segment of relativePath.split("/")) {
      if (!segment) continue
      walkedPath = `${walkedPath}${segment}/`
      paths.push(walkedPath)
    }

    return paths
  }, [
    browser.currentPath,
    browser.selection.selectedEntry,
    browser.selection.selectedPath,
  ])

  return (
    <ScrollArea
      orientation="horizontal"
      viewportClassName="overscroll-x-contain"
    >
      <div className="flex h-full min-w-full">
        {columnPaths.map((path, index) => (
          <FileSystemColumn
            key={path || "(root)"}
            controller={controller}
            isLast={index === columnPaths.length - 1}
            path={path}
          />
        ))}
      </div>
    </ScrollArea>
  )
}

function FileSystemColumn({
  controller,
  isLast,
  path,
}: {
  controller: FileSystemBrowserController
  isLast: boolean
  path: string
}) {
  const { browser, fileActions } = controller
  const viewportRef = React.useRef<HTMLDivElement | null>(null)
  const entries = React.useMemo(
    () => browser.index.children.get(path) ?? [],
    [browser.index.children, path]
  )
  const virtualizer = useVirtualizer({
    count: entries.length,
    estimateSize: () => COLUMN_ROW_HEIGHT,
    getScrollElement: () => viewportRef.current,
    overscan: 10,
  })
  const virtualRows = virtualizer.getVirtualItems()
  const renderedRows = virtualRows.length
    ? virtualRows.map((row) => ({
        entry: entries[row.index],
        start: row.start,
      }))
    : entries.map((entry, index) => ({
        entry,
        start: index * COLUMN_ROW_HEIGHT,
      }))
  const totalSize = virtualRows.length
    ? virtualizer.getTotalSize()
    : entries.length * COLUMN_ROW_HEIGHT
  const rovingFocus = useFileSystemRovingFocus({
    entries,
    getScrollIndex: (entry) =>
      entries.findIndex((candidate) => candidate.path === entry.path),
    onSelect: (entry) => {
      browser.commands.selectEntry(entry)
      if (entry.kind === "folder") {
        void browser.commands.ensureChildren(entry.path)
      }
    },
    scrollToIndex: (index) => {
      if (index !== -1) virtualizer.scrollToIndex(index)
    },
    selectedPath: browser.selection.selectedPath,
  })
  const openEntry = React.useCallback(
    (entry: FileSystemEntry) => {
      if (entry.kind === "folder") {
        browser.commands.navigateTo(entry.path)
      } else {
        fileActions.openPreview(entry)
      }
    },
    [browser.commands, fileActions]
  )
  const selectParent = React.useCallback(() => {
    const selectedEntry = browser.selection.selectedEntry
    if (!selectedEntry) return

    const parentPath =
      selectedEntry.kind === "folder"
        ? pathParent(selectedEntry.path)
        : selectedEntry.parentPath
    const parent = parentPath
      ? (browser.rawIndex.folders.get(parentPath) ?? null)
      : null

    if (parent) browser.commands.selectEntry(parent)
  }, [
    browser.commands,
    browser.rawIndex.folders,
    browser.selection.selectedEntry,
  ])
  const selectChild = React.useCallback(() => {
    const selectedEntry = browser.selection.selectedEntry
    if (selectedEntry?.kind !== "folder") return

    void browser.commands.selectFirstChildAfterEnsure(selectedEntry.path)
  }, [
    browser.commands,
    browser.rawIndex.folders,
    browser.selection.selectedEntry,
  ])
  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      rovingFocus.selectByOffset(event.key === "ArrowDown" ? 1 : -1)
      event.preventDefault()
      return
    }
    if (event.key === "Home" || event.key === "End") {
      rovingFocus.selectBoundary(event.key === "Home" ? "first" : "last")
      event.preventDefault()
      return
    }
    if (event.key === "ArrowRight") {
      selectChild()
      event.preventDefault()
      return
    }
    if (event.key === "ArrowLeft") {
      selectParent()
      event.preventDefault()
      return
    }
    if (event.key === "Enter" && browser.selection.selectedEntry) {
      openEntry(browser.selection.selectedEntry)
      event.preventDefault()
      return
    }

    rovingFocus.selectTypeAhead(event)
  }

  return (
    <div
      className={cn("w-64 shrink-0 border-r", isLast && "flex-1")}
      role="listbox"
      aria-label={path || "Files"}
      tabIndex={0}
      onKeyDown={handleKeyDown}
    >
      <div ref={viewportRef} className="h-full overflow-auto p-1.5">
        {entries.length ? (
          <div className="relative" style={{ height: totalSize }}>
            {renderedRows.map(({ entry, start }) => (
              <FileSystemColumnRow
                key={entry.path}
                controller={controller}
                entry={entry}
                ref={(element) => {
                  rovingFocus.registerEntryRef(entry.path, element)
                }}
                style={{ transform: `translateY(${start}px)` }}
              />
            ))}
          </div>
        ) : (
          <div className="px-2 py-1.5 text-xs text-muted-foreground">
            This folder is empty
          </div>
        )}
      </div>
    </div>
  )
}

const FileSystemColumnRow = React.forwardRef<
  HTMLButtonElement,
  {
    controller: FileSystemBrowserController
    entry: FileSystemEntry
    style: React.CSSProperties
  }
>(function FileSystemColumnRow({ controller, entry, style }, ref) {
  const { browser, fileActions } = controller
  const selectedPath = browser.selection.selectedPath
  const isSelected = entry.path === selectedPath
  const isOnTrail =
    entry.kind === "folder" &&
    selectedPath?.startsWith(entry.path) &&
    pathParent(selectedPath) !== entry.parentPath

  return (
    <button
      ref={ref}
      type="button"
      role="option"
      aria-selected={isSelected}
      tabIndex={isSelected || !selectedPath ? 0 : -1}
      onClick={() => {
        browser.commands.selectEntry(entry)
        if (entry.kind === "folder") {
          void browser.commands.ensureChildren(entry.path)
        }
      }}
      onDoubleClick={() => {
        if (entry.kind === "folder") {
          browser.commands.navigateTo(entry.path)
        } else {
          fileActions.openPreview(entry)
        }
      }}
      className={cn(
        "absolute inset-x-0 flex h-8 shrink-0 items-center gap-2 rounded-sm px-2 text-left text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring",
        isSelected
          ? "bg-primary text-primary-foreground"
          : isOnTrail
            ? "bg-accent"
            : "hover:bg-accent/50"
      )}
      style={style}
    >
      {entry.kind === "folder" ? (
        <Folder className="size-4 shrink-0 text-muted-foreground" aria-hidden />
      ) : (
        <FileSystemThumbnail
          file={entry}
          resolveFileSource={fileActions.resolveFileSource}
          className="w-4 shrink-0"
        />
      )}
      <span className="min-w-0 flex-1 truncate">{entry.name}</span>
      {entry.kind === "folder" && folderHasChildren(browser.rawIndex, entry) ? (
        <ChevronRight className="size-3.5 shrink-0 text-muted-foreground" />
      ) : null}
    </button>
  )
})

import { formatFileSize } from "@/components/ui/file-size-format"

export function formatFileSystemSize(size: number | undefined) {
  return typeof size === "number" ? formatFileSize(size) : ""
}

export function formatFileSystemDate(value: string | undefined) {
  if (!value) return ""

  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return ""

  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date)
}
